import{c as e,Q as o,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Tom Brown 取代 Amodei 主導 Fable 5 解禁談判（WIRED 報導）","description":"","frontmatter":{"url":"https://x.com/dotey/status/2069847686992314492","title":"Tom Brown 取代 Amodei 主導 Fable 5 解禁談判（WIRED 報導）","author":"dotey","archived":"2026-06-25T00:00:00.000Z","category":"anthropic-news","handle":"@dotey","published":"2026-06-25T00:00:00.000Z","score":4.7,"stats":"153❤ · 10 retweets","tags":["fable5","anthropic","tom-brown","export-control","trump","wired","negotiations"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-06-25-@dotey-847492.md","filePath":"research/tweets/2026-06-25-@dotey-847492.md","lastUpdated":1785909234000}'),d={name:"research/tweets/2026-06-25-@dotey-847492.md"};function s(n,t,i,h,l,p){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="tom-brown-取代-amodei-主導-fable-5-解禁談判-wired-報導-—-dotey" tabindex="-1">Tom Brown 取代 Amodei 主導 Fable 5 解禁談判（WIRED 報導）— @dotey <a class="header-anchor" href="#tom-brown-取代-amodei-主導-fable-5-解禁談判-wired-報導-—-dotey" aria-label="Permalink to &quot;Tom Brown 取代 Amodei 主導 Fable 5 解禁談判（WIRED 報導）— @dotey&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/dotey/status/2069847686992314492" target="_blank" rel="noreferrer">https://x.com/dotey/status/2069847686992314492</a><strong>類別</strong>：anthropic-news <strong>統計</strong>：153❤ · 10 retweets</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>据 WIRED 报道，在围绕 Fable 5 模型解禁的谈判中，Anthropic 联合创始人 Tom Brown 已经取代 Amodei，成为与特朗普政府对话的主要代表。一位直接了解通话内容的人士说：&quot;Tom Brown 不像 Dario 那样拧巴，他能正常沟通。&quot;</p><p>事情的起因要回到 6 月 12 日。当天美国商务部以国家安全为由，对 Anthropic 最新发布的 Fable 5 和 Mythos 5 两款模型发出出口管制令，要求禁止任何外国公民访问，包括 Anthropic 自己的外籍员工。由于无法按国籍筛选用户，Anthropic 被迫对所有用户关闭了这两款模型。</p><p>触发这一切的导火索是有公司（据报道是亚马逊的研究团队）声称找到了绕过 Fable 5 安全护栏的方法，可以释放底层 Mythos 模型的网络安全能力。Anthropic 认为这只是一个狭窄的漏洞，不构成全面的越狱，但政府没有被说服。</p><p>这是美国政府首次用出口管制手段直接下架一款 AI 模型，影响了数以亿计的用户。</p><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>3/10</td><td>政治背景，無直接技術行動</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>首次 AI 出口管制 + 談判策略角度</td></tr><tr><td>C. 證據品質 (20%)</td><td>7/10</td><td>WIRED 報導，有直接知情者引述</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>事件背景詳細，無技術細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>3/10</td><td>特定事件</td></tr><tr><td><strong>加權總分</strong></td><td><strong>4.7/10</strong></td><td>3×0.3+6×0.2+7×0.2+5×0.15+3×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip（&lt; 6.0；重要背景信號，追蹤 Fable 5 解禁進程） <strong>理由</strong>：出口管制事件背景文章，對 model-selection-grid 的 Fable 5 狀態有間接影響</p>',12)])])}const b=e(d,[["render",s]]);export{m as __pageData,b as default};
